.help-card p{margin-top:var(--g-spacing-2);line-height:20px}
.help-link{--g-button-text-color:var(--g-color-text-brand);margin-top:var(--g-spacing-2);margin-left:calc(-1 * var(--g-spacing-3));font-weight:550}
.sidebar-user{display:flex;align-items:center;gap:var(--g-spacing-3);border-top:1px solid var(--g-color-line-generic);padding-top:var(--g-spacing-5)}
.sidebar-user>:first-child{flex-shrink:0}.user-copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:var(--g-spacing-1)}.user-name{font-weight:550}
.page-content{min-height:100vh;background:var(--app-background)}
.topbar{height:72px;display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);border-bottom:1px solid var(--g-color-line-generic);padding:0 var(--g-spacing-8);background:var(--g-color-base-background)}
.breadcrumb{display:flex;align-items:center;gap:var(--g-spacing-3);color:var(--g-color-text-secondary);font-size:12px}.breadcrumb-current{color:var(--g-color-text-primary);font-weight:500}
.account-pill{display:flex;align-items:center;gap:var(--g-spacing-2);padding:var(--g-spacing-2) var(--g-spacing-3);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-xl);font-size:11px;white-space:nowrap}.status-dot{width:6px;height:6px;background:var(--g-color-base-brand);border-radius:50%}
.main-content{max-width:1136px;padding:var(--g-spacing-8) var(--g-spacing-10) var(--g-spacing-4);margin:0 auto}
.page-heading{margin-bottom:var(--g-spacing-7)}.eyebrow{text-transform:uppercase;letter-spacing:1.5px;color:var(--g-color-text-brand);font-size:10px;font-weight:650;margin-bottom:var(--g-spacing-2)}
.page-heading h1{font-weight:600;letter-spacing:-.85px}.page-heading p{margin-top:var(--g-spacing-2);line-height:22px}
.settings-card{background:var(--g-color-base-background);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);overflow:hidden;box-shadow:0 2px 5px color-mix(in srgb,var(--g-color-sfx-shadow) 9%,transparent)}
.settings-section{display:grid;grid-template-columns:230px minmax(0,1fr);gap:var(--g-spacing-8);padding:var(--g-spacing-7) var(--g-spacing-8);border-bottom:1px solid var(--g-color-line-generic);scroll-margin-top:var(--g-spacing-6)}
.section-heading p{max-width:205px;margin-top:var(--g-spacing-2);line-height:20px}.section-title{display:flex;align-items:center;gap:var(--g-spacing-2)}.section-title>svg{color:var(--g-color-text-secondary);flex-shrink:0}.section-title h2{font-weight:600}.section-controls{min-width:0}
.avatar-row{display:flex;gap:var(--g-spacing-5);align-items:center;margin-bottom:var(--g-spacing-6)}.avatar-wrap{position:relative;flex-shrink:0}.avatar-wrap>:first-child{--g-avatar-size:76px;--g-avatar-text-font-size:26px}
.avatar-decoration{position:absolute;right:0;bottom:2px;width:22px;height:22px;display:grid;place-items:center;border:3px solid var(--g-color-base-background);border-radius:50%;background:var(--g-color-base-brand);color:var(--g-color-text-brand-contrast)}
.avatar-options{display:flex;flex-direction:column;align-items:flex-start;gap:var(--g-spacing-2);min-width:0}.avatar-buttons{display:flex;gap:var(--g-spacing-1);flex-wrap:wrap}.field-label{font-weight:500}
.personal-fields{display:grid;gap:var(--g-spacing-4)}.field{display:flex;flex-direction:column;gap:var(--g-spacing-2);min-width:0}.field>label{font-size:13px;font-weight:500}.field>span:last-child{line-height:17px}
.field{--g-text-input-border-color:var(--g-color-line-generic);--g-text-input-border-color-hover:var(--g-color-text-hint);--g-text-input-border-color-active:var(--g-color-line-brand)}.field svg{color:var(--g-color-text-hint);margin-left:var(--g-spacing-3)}
.preference-fields{display:grid;gap:var(--g-spacing-4)}
.security-row{display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4)}.security-row>div{flex:1;min-width:0}.security-row>:last-child{flex-shrink:0}.security-title{display:flex;align-items:center;gap:var(--g-spacing-2);flex-wrap:wrap}
.recommended{display:inline-flex;color:var(--g-color-text-brand);background:var(--g-color-base-selection);border-radius:var(--g-border-radius-s);padding:var(--g-spacing-1) var(--g-spacing-2);font-size:10px;line-height:13px}
.security-row p{margin-top:var(--g-spacing-2);line-height:20px;max-width:330px}.security-note{display:flex;gap:var(--g-spacing-2);color:var(--g-color-text-secondary);background:var(--g-color-base-generic);border-radius:var(--g-border-radius-m);padding:var(--g-spacing-3);margin-top:var(--g-spacing-4);font-size:12px;line-height:18px}.security-note svg{flex-shrink:0;margin-top:var(--g-spacing-1)}
.notification-heading{font-weight:500;display:block;margin-bottom:var(--g-spacing-4)}.notification-list{display:flex;flex-direction:column;align-items:flex-start;gap:var(--g-spacing-4)}.checkbox-copy{display:flex;flex-direction:column;gap:var(--g-spacing-1);padding-left:var(--g-spacing-1)}.checkbox-title{font-size:13px;font-weight:500;line-height:20px}.checkbox-copy>:last-child{line-height:19px}
.form-footer{display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);background:color-mix(in srgb,var(--app-background) 65%,var(--g-color-base-background));padding:var(--g-spacing-5) var(--g-spacing-8)}
.save-status{display:flex;align-items:center;gap:var(--g-spacing-2);color:var(--g-color-text-secondary);font-size:11px}.save-status svg{color:var(--g-color-text-brand);flex-shrink:0}.save-status.is-dirty{color:var(--g-color-text-brand)}.form-actions{display:flex;gap:var(--g-spacing-3);flex-shrink:0}.form-actions>:last-child{min-width:120px}
.privacy-note{display:flex;align-items:center;gap:var(--g-spacing-3);margin:var(--g-spacing-6) 0 var(--g-spacing-8);justify-content:center}.privacy-icon{color:var(--g-color-text-secondary);flex-shrink:0}.privacy-note p{margin-top:var(--g-spacing-1)}.privacy-note>div>:first-child{color:var(--g-color-text-secondary);font-size:12px}
.page-footer{display:flex;justify-content:space-between;border-top:1px solid var(--g-color-line-generic);color:var(--g-color-text-hint);font-size:10px;padding-top:var(--g-spacing-4)}
.field-error,.save-error{color:var(--g-color-text-danger);font-size:12px;line-height:20px;margin-bottom:var(--g-spacing-3)}.save-error{margin-top:var(--g-spacing-3)}
.notice{position:fixed;z-index:100;left:50%;bottom:var(--g-spacing-7);transform:translateX(-50%);display:flex;align-items:center;gap:var(--g-spacing-3);background:var(--g-color-base-background);border:1px solid var(--g-color-line-generic);box-shadow:0 6px 30px color-mix(in srgb,var(--g-color-sfx-shadow) 35%,transparent);border-radius:var(--g-border-radius-l);padding:var(--g-spacing-4) var(--g-spacing-5);font-size:13px;max-width:calc(100vw - 32px);width:max-content;animation:toast-in 180ms ease-out}.notice-icon{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;color:var(--g-color-text-brand);background:var(--g-color-base-selection)}
.help-modal{max-width:460px;padding:var(--g-spacing-8);display:flex;flex-direction:column;align-items:flex-start;gap:var(--g-spacing-5)}.help-modal>svg{color:var(--g-color-text-brand)}.help-modal p{line-height:24px}
@keyframes toast-in{from{opacity:0;translate:0 8px}to{opacity:1;translate:0 0}}
@media(min-width:1500px){.main-content{padding-top:var(--g-spacing-10)}.page-heading{margin-bottom:var(--g-spacing-8)}}
@media(max-width:1150px){.settings-section{grid-template-columns:185px minmax(0,1fr);gap:var(--g-spacing-5);padding:var(--g-spacing-6)}.main-content{padding-right:var(--g-spacing-7);padding-left:var(--g-spacing-7)}.section-title{gap:var(--g-spacing-2)}.section-title h2{font-size:14px}.form-footer{padding:var(--g-spacing-5) var(--g-spacing-6)}}
@media(max-width:999px){.sidebar-brand{padding:var(--g-spacing-6) var(--g-spacing-5)}.brand>span:last-child,.brand-caption{display:none}.nav-caption{padding:var(--g-spacing-4) var(--g-spacing-6);letter-spacing:0}.sidebar-bottom{padding:var(--g-spacing-4)}.sidebar-user{justify-content:center}}
@media(max-width:700px){.main-content{padding:var(--g-spacing-6) var(--g-spacing-4)}.topbar{height:60px;padding:0 var(--g-spacing-4)}.account-pill{display:none}.breadcrumb{gap:var(--g-spacing-2)}.settings-section{grid-template-columns:minmax(0,1fr);gap:var(--g-spacing-5);padding:var(--g-spacing-5)}.section-heading p{max-width:none}.page-heading h1{font-size:25px;line-height:32px}.page-heading p{font-size:13px;line-height:20px}.page-heading{margin-bottom:var(--g-spacing-5)}.form-footer{padding:var(--g-spacing-5);flex-direction:column-reverse;align-items:stretch}.form-actions{justify-content:flex-end}.save-status{justify-content:center}.avatar-row{gap:var(--g-spacing-3);align-items:flex-start}.avatar-wrap>:first-child{--g-avatar-size:52px;--g-avatar-text-font-size:20px}.avatar-options>:last-child{font-size:10px}.page-footer>:last-child{display:none}.privacy-note{align-items:flex-start}.privacy-note p{line-height:18px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto"'!important;animation:none!important}}
EOF
npm run build'
